import os, ctypes, subprocess
import numpy as np

_dir = os.path.dirname(os.path.abspath(__file__))
_so = os.path.join(_dir, "lap.so")
_lib = None
try:
    if not os.path.exists(_so):
        subprocess.run(["gcc", "-O3", "-march=native", "-shared", "-fPIC", "-o", _so, os.path.join(_dir, "lap.c")],
                       check=True, env=dict(os.environ, TMPDIR=os.path.join(_dir, "tmp")))
    _lib = ctypes.CDLL(_so)
    _lib.solve.restype = ctypes.c_int
    _lib.solve.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_void_p]
except Exception:
    _lib = None


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if (_lib is None or M.shape != (n, n) or b.shape[0] != n or n == 0
                or not np.all(a == a[0]) or not np.all(b == a[0])):
            return {"transport_plan": _fallback(a, b, M)}
        r2c = np.empty(n, dtype=np.int32)
        for K in (min(n, 20), n):
            ret = _lib.solve(n, M.ctypes.data, K, r2c.ctypes.data)
            if ret == 0:
                break
        if ret != 0:
            return {"transport_plan": _fallback(a, b, M)}
        G = np.zeros((n, n))
        G[np.arange(n), r2c] = a[0]
        return {"transport_plan": G}

