/* returns 0 on success, fills row4col (col per row). */
static int ssp(int n, const double *C, const int *adj, int K, int *r2c, int *c2r,
               double *u, double *v, double *dist, int *path, int *sc, int *srl, int *scl,
               int *heap, int *hpos){
  for(int f=0; f<n; f++){
