      srl[nsr++]=i;
      const int *a=adj+(size_t)i*K; const double *Ci=C+(size_t)i*n; double ui=u[i];
      for(int t=0;t<K;t++){int j=a[t]; if(sc[j]) continue;
        double r=minVal+Ci[j]-ui-v[j];
        if(r<dist[j]){dist[j]=r; path[j]=i;
          int p=hpos[j]; if(p<0){p=hn++; heap[p]=j;}
          while(p>0){int q=(p-1)/2; if(dist[heap[q]]<=r) break; heap[p]=heap[q]; hpos[heap[p]]=p; p=q;}
          heap[p]=j; hpos[j]=p;}
      }
      if(hn==0) return -1;
      int j=heap[0]; hpos[j]=-2; hn--;
      if(hn>0){int x=heap[hn]; double dx=dist[x]; int p=0;
        while(1){int c=2*p+1; if(c>=hn) break; if(c+1<hn && dist[heap[c+1]]<dist[heap[c]]) c++;
          if(dist[heap[c]]>=dx) break; heap[p]=heap[c]; hpos[heap[p]]=p; p=c;}
        heap[p]=x; hpos[x]=p;}
      minVal=dist[j]; sc[j]=1; scl[nsc++]=j;
      if(c2r[j]<0){sink=j;break;}
      i=c2r[j];
    }
    u[f]+=minVal;
    for(int t=1;t<nsr;t++){int ii=srl[t]; u[ii]+=minVal-dist[r2c[ii]];}
    for(int t=0;t<nsc;t++){int jj=scl[t]; v[jj]-=minVal-dist[jj];}
    int j=sink;
    while(1){int ii=path[j]; c2r[j]=ii; int tmp=r2c[ii]; r2c[ii]=j; if(ii==f) break; j=tmp;}
  }
  return 0;
}

int solve(int n, const double *C, int K, int *r2c){
  int *adj=malloc(sizeof(int)*(size_t)n*K);
  double *kd=malloc(sizeof(double)*K);
  int *c2r=malloc(sizeof(int)*n*6); int *path=c2r+n,*sc=path+n,*srl=sc+n,*scl=srl+n,*heap=scl+n;
  int *hpos=malloc(sizeof(int)*n);
  double *u=malloc(sizeof(double)*n*3),*v=u+n,*dist=v+n;
  int ret=0;
  for(int i=0;i<n;i++){
    const double *Ci=C+(size_t)i*n; int *a=adj+(size_t)i*K; int m=0;
    for(int j=0;j<n;j++){double c=Ci[j];
      if(m<K){int p=m++; while(p>0&&kd[p-1]>c){kd[p]=kd[p-1];a[p]=a[p-1];p--;} kd[p]=c;a[p]=j;}
      else if(c<kd[K-1]){int p=K-1; while(p>0&&kd[p-1]>c){kd[p]=kd[p-1];a[p]=a[p-1];p--;} kd[p]=c;a[p]=j;}
    }
  }
  for(int j=0;j<n;j++){c2r[j]=-1; v[j]=0;}
  for(int i=0;i<n;i++){int j=adj[(size_t)i*K]; u[i]=C[(size_t)i*n+j];
    if(c2r[j]<0){c2r[j]=i;r2c[i]=j;} else r2c[i]=-1;}
  if(ssp(n,C,adj,K,r2c,c2r,u,v,dist,path,sc,srl,scl,heap,hpos)){ret=-1;goto done;}
  for(int i=0;i<n && !ret;i++){const double *Ci=C+(size_t)i*n; double ui=u[i];
    for(int j=0;j<n;j++) if(Ci[j]-ui-v[j] < -1e-12){ret=-2;break;}}
done:
  free(adj);free(kd);free(c2r);free(hpos);free(u);
  return ret;
}
