static double qsel(double *a, int n, int k){
  int lo=0, hi=n-1;
  while(hi>lo){
    double p=a[(lo+hi)/2]; int i=lo,j=hi;
    while(i<=j){while(a[i]<p)i++; while(a[j]>p)j--; if(i<=j){double t=a[i];a[i]=a[j];a[j]=t;i++;j--;}}
    if(k<=j) hi=j; else if(k>=i) lo=i; else return a[k];
  }
  return a[k];
}

typedef struct { int n; int *rp; int *ci; double *cw; int cap; } G;

static void build(G *g, const double *C, double thr, int *cdeg, const int *extra_row, const double *rowthr){
  int n=g->n, m=0;
  for(int j=0;j<n;j++) cdeg[j]=0;
  for(int i=0;i<n;i++){
    const double *Ci=C+(size_t)i*n; double t=rowthr?rowthr[i]:thr;
    if(m+n>g->cap){ g->cap=(m+n)*2; g->ci=realloc(g->ci,sizeof(int)*g->cap); g->cw=realloc(g->cw,sizeof(double)*g->cap); }
    g->rp[i]=m; int *ci=g->ci; double *cw=g->cw;
    for(int j=0;j<n;j++){ double c=Ci[j]; ci[m]=j; cw[m]=c; m+=(c<=t); }
    for(int t2=g->rp[i];t2<m;t2++) cdeg[ci[t2]]++;
  }
  g->rp[n]=m;
}

/* Dijkstra SSP on sparse graph for free rows */
static int ssp(G *g, int *r2c, int *c2r, double *u, double *v, double *dist, int *path, char *sc,
               int *srl, int *scl, int *heap, int *hpos, int *touch, const int *rows, int nrows){
  int n=g->n; int fails=0;
  for(int q=0;q<nrows;q++){
    int f=rows[q]; if(r2c[f]>=0) continue;
    int hn=0,nsr=0,nsc=0,nh=0,i=f,sink=-1; double minVal=0;
    while(1){
      srl[nsr++]=i; ST[1]++;
      int s=g->rp[i], e=g->rp[i+1]; double ui=u[i];
      for(int t=s;t<e;t++){int j=g->ci[t]; if(sc[j]) continue;
        double r=minVal+g->cw[t]-ui-v[j];
        if(r<dist[j]){ if(hpos[j]==-1) touch[nh++]=j; dist[j]=r; path[j]=i;
          int p=hpos[j]; if(p<0){p=hn++;}
          while(p>0){int q2=(p-1)>>1; if(dist[heap[q2]]<=r) break; heap[p]=heap[q2]; hpos[heap[p]]=p; p=q2;}
          heap[p]=j; hpos[j]=p;}
      }
      if(hn==0) break;
      int j=heap[0]; hpos[j]=-2; hn--;
      if(hn>0){int x=heap[hn]; double dx=dist[x]; int p=0;
        while(1){int c=2*p+1; if(c>=hn) break; if(c+1<hn && dist[heap[c+1]]<dist[heap[c]]) c++;
          if(dist[heap[c]]>=dx) break; heap[p]=heap[c]; hpos[heap[p]]=p; p=c;}
        heap[p]=x; hpos[x]=p;}
      minVal=dist[j]; sc[j]=1; scl[nsc++]=j;
      if(c2r[j]<0){sink=j;break;}
      i=c2r[j];
    }
    if(sink>=0){
      u[f]+=minVal;
      for(int t=1;t<nsr;t++){int ii=srl[t]; u[ii]+=minVal-dist[r2c[ii]];}
      for(int t=0;t<nsc;t++){int jj=scl[t]; v[jj]-=minVal-dist[jj];}
      int j=sink;
      while(1){int ii=path[j]; c2r[j]=ii; int tmp=r2c[ii]; r2c[ii]=j; if(ii==f) break; j=tmp;}
    } else fails++;
    for(int t=0;t<nh;t++){int jj=touch[t]; dist[jj]=INFINITY; sc[jj]=0; hpos[jj]=-1;}
  }
  return fails;
}

