static int dense_fix(int n, const double *C, G *g, double *p, int *r2c, int *c2r, int *fr, double tol, double addm, char *in, int *nfo){
  int nf=0;
  for(int i=0;i<n;i++){
    const double *Ci=C+(size_t)i*n;
    double m0=INFINITY,m1=INFINITY,m2=INFINITY,m3=INFINITY; int j=0;
    for(;j+4<=n;j+=4){double r0=Ci[j]+p[j],r1=Ci[j+1]+p[j+1],r2=Ci[j+2]+p[j+2],r3=Ci[j+3]+p[j+3];
      m0=r0<m0?r0:m0; m1=r1<m1?r1:m1; m2=r2<m2?r2:m2; m3=r3<m3?r3:m3;}
    for(;j<n;j++){double r=Ci[j]+p[j]; m0=r<m0?r:m0;}
    double m=fmin(fmin(m0,m1),fmin(m2,m3));
    int j0=r2c[i];
    if(j0<0 || Ci[j0]+p[j0] > m+tol){
      int s=g->rp[i], L=g->len[i], cap=g->rp[i+1]-s;
      for(int t=s;t<s+L;t++) in[g->ci[t]]=1;
      double lim=m+addm;
      for(int jj=0;jj<n;jj++){ if(!in[jj] && Ci[jj]+p[jj]<lim && L<cap){ g->ci[s+L]=jj; g->cw[s+L]=Ci[jj]; L++; } }
      for(int t=s;t<s+L;t++) in[g->ci[t]]=0;
      g->len[i]=L;
      if(j0>=0){ r2c[i]=-1; c2r[j0]=-1; }
      fr[nf++]=i;
    }
  }
  *nfo=nf; return nf;
}
