/* dense JV-style shortest augmenting path, returns duals */
void lsa(int n, const double *C, int *r2c, double *u, double *v){
  int *c2r=malloc(sizeof(int)*n),*path=malloc(sizeof(int)*n),*todo=malloc(sizeof(int)*n),*srl=malloc(sizeof(int)*n),*scl=malloc(sizeof(int)*n);
  double *dist=malloc(sizeof(double)*n);
  for(int j=0;j<n;j++){c2r[j]=-1;v[j]=0;} for(int i=0;i<n;i++){r2c[i]=-1;u[i]=0;}
  for(int f=0;f<n;f++){
    int nt=0; for(int j=0;j<n;j++){dist[j]=INFINITY;todo[nt++]=j;}
    int nsr=0,nsc=0,i=f,sink; double mv=0;
    while(1){ srl[nsr++]=i; const double *Ci=C+(size_t)i*n; double best=INFINITY; int bk=0;
      for(int k=0;k<nt;k++){int j=todo[k]; double r=mv+Ci[j]-u[i]-v[j]; if(r<dist[j]){dist[j]=r;path[j]=i;} if(dist[j]<best){best=dist[j];bk=k;}}
      int j=todo[bk]; todo[bk]=todo[--nt]; mv=best; scl[nsc++]=j; if(c2r[j]<0){sink=j;break;} i=c2r[j]; }
    u[f]+=mv; for(int t=1;t<nsr;t++){int ii=srl[t]; u[ii]+=mv-dist[r2c[ii]];}
    for(int t=0;t<nsc;t++){int jj=scl[t]; v[jj]-=mv-dist[jj];}
    int j=sink; while(1){int ii=path[j]; c2r[j]=ii; int tmp=r2c[ii]; r2c[ii]=j; if(ii==f)break; j=tmp;}
  }
}
